//! OpenCode's design language as a Rune theme: `@opencode/ui`'s tokens (as the browser resolves
//! them, `assets/theme.json`, regenerated by `tools/theme.mjs`), its fonts and its icon catalog,
//! mapped onto rune-kit's semantic schema. Nothing here is compiled into Rune's core.
//!
//! ```ignore
//! let k = rune_theme_opencode::kit(cx.system_dark());
//! rune_kit::Button::new("Save").build(k)
//! ```

pub mod icons;

use std::sync::OnceLock;

use rune::{Color, TextStyle, Theme};
use rune_kit::{Elevation, Glyphs, Kit, Motion, Palette, Radius, StateColors, Type, css, glyphs};
use serde_json::Value;

/// The theme as data: palette, light and dark tokens, computed shadows and numbers.
pub const THEME: &str = include_str!("../assets/theme.json");

/// Inter (variable) and IBM Plex Mono, for `AppSpec::fonts`.
pub const FONTS: &[&[u8]] = &[
    include_bytes!("../assets/fonts/InterVariable.ttf"),
    include_bytes!("../assets/fonts/IBMPlexMono-Regular.ttf"),
    include_bytes!("../assets/fonts/IBMPlexMono-Medium.ttf"),
];

/// `AppSpec::families`: (sans, mono).
pub const FAMILIES: (&str, &str) = ("Inter", "IBM Plex Mono");

/// The resolved `rune::Theme` for one appearance (every `--*` colour token by name, without `--`).
pub fn theme(dark: bool) -> &'static Theme {
    static DARK: OnceLock<Theme> = OnceLock::new();
    static LIGHT: OnceLock<Theme> = OnceLock::new();
    let load = || Theme::from_json(THEME, dark).unwrap_or_else(|e| panic!("{e}"));
    if dark { DARK.get_or_init(load) } else { LIGHT.get_or_init(load) }
}

/// The theme without sRGB re-solving: translucent tokens keep their authored alpha.
fn raw_theme(dark: bool) -> &'static Theme {
    static DARK: OnceLock<Theme> = OnceLock::new();
    static LIGHT: OnceLock<Theme> = OnceLock::new();
    let load = || {
        let mut v: Value = serde_json::from_str(THEME).expect("theme.json");
        v.as_object_mut().expect("theme object").remove("blend");
        Theme::from_json(&v.to_string(), dark).unwrap_or_else(|e| panic!("{e}"))
    };
    if dark { DARK.get_or_init(load) } else { LIGHT.get_or_init(load) }
}

/// The kit tokens for one appearance.
pub fn kit(dark: bool) -> &'static Kit {
    static DARK: OnceLock<Kit> = OnceLock::new();
    static LIGHT: OnceLock<Kit> = OnceLock::new();
    if dark { DARK.get_or_init(|| build(true)) } else { LIGHT.get_or_init(|| build(false)) }
}

/// Inter at a variable weight with the kit's tracking (`-0.04px` at 13, `0.05px` at 11).
const fn inter(size: f32, weight: f32, line: f32, tracking: f32) -> TextStyle {
    TextStyle::new(size, weight).lh(line).tracking(tracking)
}

pub const GLYPHS: Glyphs = Glyphs {
    copy: &icons::COPY,
    search: &icons::MAGNIFYING_GLASS,
    circle_x: &icons::CIRCLE_X,
    triangle_down: &icons::FILL_TRIANGLE_DOWN,
    clear: &icons::XMARK_SMALL,
    close: &icons::CLOSE,
    ..glyphs::DEFAULT
};

fn build(dark: bool) -> Kit {
    let t = theme(dark);
    let c = |n: &str| t.color(n);
    let v = |n: &str| t.color(&format!("v2-{n}"));
    let raw = |n: &str| raw_theme(dark).color(&format!("v2-{n}"));
    let state = |n: &str, icon: Color| StateColors {
        bg: v(&format!("state-bg-{n}")),
        fg: v(&format!("state-fg-{n}")),
        border: v(&format!("state-border-{n}")),
        icon,
    };
    let blend = v("background-bg-base");
    let solve = |x: Color| rune::theme::srgb_equivalent(x, blend);
    let data: Value = serde_json::from_str(THEME).expect("theme.json");
    let mode = if dark { "dark" } else { "light" };
    let sh = |n: &str| {
        let src = data["shadows"][mode][n].as_str().unwrap_or_else(|| panic!("theme.json has no {mode} shadow {n:?}"));
        css::box_shadows(src, solve)
    };
    let opaque = |n: &str| t.color(n).alpha(1.0);
    // Tokens some components read but the kit never defines resolve as CSS does: no colour
    // (transparent backgrounds) or the inherited text colour.
    let or = |n: &str, fallback: Color| t.try_color(n).unwrap_or(fallback);
    let palette = Palette {
        page: c("background-base"),
        bg_base: blend,
        bg_deep: v("background-bg-deep"),
        layer_01: v("background-bg-layer-01"),
        layer_02: v("background-bg-layer-02"),
        layer_03: v("background-bg-layer-03"),
        layer_04: v("background-bg-layer-04"),
        bg_inverse: v("background-bg-inverse"),
        bg_contrast: v("background-bg-contrast"),
        bg_button_neutral: v("background-bg-button-neutral"),
        bg_icon_button_contrast: v("background-bg-icon-button-contrast"),
        bg_accent: v("background-bg-accent"),
        submit_highlight: if dark { raw("alpha-light-60") } else { raw("alpha-light-20") },
        submit_hover: if dark { raw("alpha-dark-8") } else { raw("overlay-simple-overlay-contrast-hover") },
        submit_fg: if dark { v("text-text-inverse") } else { v("text-text-contrast") },
        submit_icon: if dark { v("icon-icon-inverse") } else { v("text-text-contrast") },
        text_base: v("text-text-base"),
        text_muted: v("text-text-muted"),
        text_faint: v("text-text-faint"),
        text_inverse: v("text-text-inverse"),
        text_contrast: v("text-text-contrast"),
        text_accent: v("text-text-accent"),
        icon_base: v("icon-icon-base"),
        icon_muted: v("icon-icon-muted"),
        icon_faint: v("icon-icon-faint"),
        icon_inverse: v("icon-icon-inverse"),
        icon_contrast: v("icon-icon-contrast"),
        icon_accent: v("icon-icon-accent"),
        border_muted: v("border-border-muted"),
        border_base: v("border-border-base"),
        border_strong: v("border-border-strong"),
        border_focus: v("border-border-focus"),
        hover: v("overlay-simple-overlay-hover"),
        pressed: v("overlay-simple-overlay-pressed"),
        contrast_hover: raw("overlay-simple-overlay-contrast-hover"),
        contrast_pressed: raw("overlay-simple-overlay-contrast-pressed"),
        scrim: v("overlay-simple-overlay-scrim"),
        depth_top: raw("overlay-gradient-depth-overlay-depth-top"),
        depth_bottom: raw("overlay-gradient-depth-overlay-depth-bot"),
        white: opaque("v2-alpha-light-100"),
        black: opaque("v2-alpha-dark-100"),
        knob: v("grey-200"),
        knob_on: v("grey-300"),
        success: state("success", c("icon-success-active")),
        warning: state("warning", c("icon-warning-active")),
        danger: state("danger", v("state-fg-danger")),
        info: state("info", c("icon-info-active")),
        surface_base: c("surface-base"),
        surface_weak: c("surface-weak"),
        surface_hover: or("surface-hover", Color::TRANSPARENT),
        surface_raised: c("surface-raised-stronger-non-alpha"),
        surface_raised_base: c("surface-raised-base"),
        surface_raised_hover: c("surface-raised-base-hover"),
        surface_float: c("surface-float-base"),
        surface_disabled: or("surface-disabled", Color::TRANSPARENT),
        border_weak: c("border-weak-base"),
        border_hover: c("border-hover"),
        border_active: c("border-active"),
        border_disabled: c("border-disabled"),
        text_strong: c("text-strong"),
        text_weak: c("text-weak"),
        text_invert_strong: c("text-invert-strong"),
        icon_weaker: or("icon-weaker", c("text-base")),
        std_border: c("border-base"),
        std_icon: c("icon-base"),
        std_icon_invert: c("icon-invert-base"),
        std_icon_strong: c("icon-strong-base"),
        std_text: c("text-base"),
    };
    let elevation = Elevation {
        raised: sh("v2-elevation-raised"),
        floating: sh("v2-elevation-floating"),
        overlay: sh("v2-elevation-overlay"),
        button_neutral: sh("v2-elevation-button-neutral"),
        button_contrast: sh("v2-elevation-button-contrast"),
        elements: sh("v2-elevation-elements"),
        switch_off: sh("v2-elevation-switch-off"),
        switch_on: sh("v2-elevation-switch-on"),
        md: sh("shadow-md"),
        // switch.css, standard appearance: rgba(19, 16, 16, .04/.06/.08).
        knob: css::box_shadows(
            "#1310100a 0px 1px 2px -1px, #1310100f 0px 1px 2px 0px, #13101014 0px 1px 3px 0px",
            solve,
        ),
    };
    // `line-height-large` is 150%; the older text styles derive their line from it.
    let ty = Type {
        ui: inter(13.0, 440.0, 20.0, -0.04),
        ui_medium: inter(13.0, 530.0, 20.0, -0.04),
        ui_compact: inter(13.0, 440.0, 16.0, -0.04),
        small: inter(11.0, 440.0, 12.0, 0.05),
        small_medium: inter(11.0, 530.0, 12.0, 0.05),
        body: inter(14.0, 400.0, 21.0, 0.0),
        body_medium: inter(14.0, 500.0, 21.0, 0.0),
        text_small: inter(13.0, 400.0, 19.5, 0.0),
        text_small_medium: inter(13.0, 500.0, 19.5, 0.0),
        text_xsmall: inter(12.0, 400.0, 18.0, 0.0),
        text_xsmall_medium: inter(12.0, 500.0, 18.0, 0.0),
        mono: TextStyle::new(12.0, 400.0).mono().lh(18.0),
    };
    Kit {
        dark,
        c: palette,
        elevation,
        glyph: GLYPHS,
        ty,
        radius: Radius { xs: 2.0, sm: 4.0, md: 6.0, lg: 8.0, xl: 10.0 },
        // The web's 85–170 ms ease-outs, as critically damped springs of similar feel.
        motion: Motion {
            control: rune::Spring::new(0.2, 0.0),
            overlay: rune::Spring::new(0.24, 0.0),
            disclosure: rune::Spring::new(0.3, 0.0),
        },
        blend_over: Some(blend),
        ring: None,
    }
}

#[cfg(test)]
mod tests {
    #[test]
    fn both_appearances_resolve() {
        for dark in [false, true] {
            let k = super::kit(dark);
            assert!(!k.elevation.button_neutral.is_empty());
            assert_eq!(k.dark, dark);
        }
    }
}
